class Refusal(RuntimeError):
    pass

def sha_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()

def sha_file(path: Path) -> str:
    return sha_bytes(path.read_bytes())

def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))

def write_json(path: Path, value: Any) -> None:
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")

def verify_frozen() -> dict[str, str]:
    actual = {name: sha_file(ROOT / name) for name in FROZEN}
    mismatch = {name: {"expected": FROZEN[name], "actual": actual[name]}
                for name in FROZEN if actual[name] != FROZEN[name]}
    if mismatch:
        raise Refusal("frozen input digest mismatch: " + json.dumps(mismatch, sort_keys=True))
    return actual

def load_cohort() -> tuple[list[dict[str, Any]], dict[str, Any]]:
    cohort = read_json(COMPAT / "cohort-inputs.json")
    rows = cohort.get("rows")
    keys = {"curve_uid", "curve_id", "label", "n", "p", "ordinal", "seed_hex", "timestamp"}
    if (not isinstance(rows, list) or len(rows) != 21 or
            len({row.get("curve_uid") for row in rows}) != 21 or
            sum(row.get("label") == "omitted" for row in rows) != 11 or
            sum(row.get("label") == "published" for row in rows) != 10 or
            any(set(row) != keys for row in rows)):
        raise Refusal("cohort is not the exact 21-row, 11/10 frozen manifest")
    return rows, read_json(COMPAT / "runtime-bindings.json")

def integer(value: Any) -> int:
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        return int(value, 0)
    raise Refusal("non-integer provenance field")

def canonical_sources() -> dict[str, dict[str, Any]]:
    omitted = read_json(ROOT / "research/nist_seed_skipped_curves_20261016/assessed.json").get("candidate_rows")
    published = read_json(ROOT / "research/nist_seed_skipped_curves_20261016/traits.json").get("published_controls")
    if not isinstance(omitted, list) or len(omitted) != 11 or not isinstance(published, list) or len(published) != 10:
        raise Refusal("canonical source arrays unavailable or wrong cardinality")
    result: dict[str, dict[str, Any]] = {}
    for expected_label, records in (("omitted", omitted), ("published", published)):
        for record in records:
            identity = record.get("identity", {})
            uid = identity.get("curve_uid")
            if not isinstance(uid, str) or uid in result:
                raise Refusal("duplicate/missing canonical provenance UID")
            record = dict(record)
            record["_canonical_label"] = expected_label
            result[uid] = record
    return result

def prior_mapping(rows: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    sources = canonical_sources()
    corpus = [json.loads(line) for line in
              (ROOT / "research/nist_seed_selection_20261016/raw/full_prime_order_certificates.jsonl").read_text().splitlines() if line]
    answer: dict[str, dict[str, Any]] = {}
    for row in rows:
        source = sources.get(row["curve_uid"])
        if source is None or source["_canonical_label"] != row["label"]:
            raise Refusal("canonical source label/UID mismatch")
        identity = source.get("identity", {})
        curve = identity.get("curve", {})
        if identity.get("curve_id") != row["curve_id"] or integer(source["n_hex"]) != integer(row["n"]) or integer(source["p_hex"]) != integer(row["p"]):
            raise Refusal("provenance curve_id/p/n mismatch")
        if curve.get("cofactor") != 1 or integer(curve.get("subgroup_order")) != integer(row["n"]):
            raise Refusal("provenance cofactor/order mismatch")
        matches = [entry for entry in corpus if entry.get("side") == "canonical" and
                   integer(entry.get("n")) == integer(row["n"]) and integer(entry.get("p")) == integer(row["p"]) and
                   entry.get("index") == row["ordinal"] and str(entry.get("seed", "")).lower() == row["seed_hex"].lower()]
        if len(matches) != 1:
            raise Refusal("prior corpus mapping is not unique")
        entry = matches[0]
        if integer(entry["b"]) != integer(source["b_hex"]):
            raise Refusal("full curve b parameter mismatch")
        if not all(entry.get(key) is True for key in ("on_curve", "n_prime_pari", "n_times_point_identity", "order_certified", "n_in_hasse_interval", "hasse_interval_narrower_than_n")):
            raise Refusal("incomplete prior certificate booleans")
        answer[row["curve_uid"]] = {
            "corpus_record_sha256": sha_bytes(json.dumps(entry, sort_keys=True, separators=(",", ":")).encode()),
            "provenance_record_sha256": sha_bytes(json.dumps(source, sort_keys=True, separators=(",", ":")).encode()),
            "canonical_side": "canonical", "order": row["n"],
        }
    if set(answer) != {row["curve_uid"] for row in rows}:
        raise Refusal("incomplete prior-primality mapping")
    return answer

def parse_dfd(data_path: Path) -> dict[int, list[dict[str, Any]]]:
    """Parse only ecpp.DfD records: ((factors) D sign-code), never arbitrary bytes."""
    raw = (data_path / "ecpp.DfD").read_bytes()
    result: dict[int, list[dict[str, Any]]] = {}
    record = re.compile(rb"\(\(([^)]*)\)\s+(-?\d+)\s+(-?\d+)\)")
    for ordinal, match in enumerate(record.finditer(raw)):
        d = int(match.group(2))
        item = {"file": "ecpp.DfD", "record": ordinal, "byte_offset": match.start(2),
                "line": raw.count(b"\n", 0, match.start(2)) + 1,
                "factors": match.group(1).decode("ascii").split(),
                "sign_code": int(match.group(3))}
        result.setdefault(d, []).append(item)
    if not result or 0 not in result or 1 not in result:
        raise Refusal("ecpp.DfD parser did not recover required special records")
    return result

def extract_trace(serial: bytes, data_path: Path | None = None) -> dict[str, Any]:
    catalog = parse_dfd(DATA if data_path is None else data_path)
    patterns = [
        ("phase", re.compile(rb"^% Starting phase [^\r\n]*$")),
        ("proving_job", re.compile(rb"^% Starting proving job for step \d+$")),
        ("recursive_N", re.compile(rb"^% N_(\d+)=(\d+)$")),
        ("recursive_status", re.compile(rb"^% N_\d+ is (?:not )?prime$")),
        ("retry", re.compile(rb"^%!% Forced to retry, snif\.\.\.$")),
        ("D", re.compile(rb"^% (?:next D is |D\[\[\d+\]=)(-?\d+)$")),
        ("factor_route", re.compile(rb"^% (?:Factorization completed using |Using complete factorization theorem).*?$")),
        ("unknown_marker", re.compile(rb"^%!?%?.*$")),
    ]
    events: list[dict[str, Any]] = []
    for line_match in re.finditer(rb"[^\n]*(?:\n|$)", serial):
        raw_line = line_match.group(0).rstrip(b"\n").rstrip(b"\r")
        if not raw_line:
            continue
        for kind, pattern in patterns:
            found = pattern.match(raw_line)
            if found is None:
                continue
            event: dict[str, Any] = {"kind": kind, "printed": True,
                                     "source_offset": line_match.start(),
                                     "raw_utf8": raw_line.decode("utf-8", "replace")}
            if kind == "D":
                d = int(found.group(1))
                event["value"] = d
                event["catalog_positions"] = catalog.get(d, [])
            elif found.groups():
                event["value"] = [group.decode("ascii") for group in found.groups()]
            events.append(event)
            break
    return {"schema": "trace_schema.json", "raw_serial_sha256": sha_bytes(serial), "events": events,
            "unprinted_state": "UNOBSERVED",
            "inference_prohibited": "unprinted branches are not reconstructed as attempted"}

def verify_supervisor(output: Path, binding: Path, index: int, digests: dict[str, str]) -> dict[str, Any]:
    if not output.is_dir() or not binding.is_file():
        raise Refusal("supervisor directory and exact binding manifest are required")
    names = {path.name for path in output.iterdir()}
    if not SUPERVISOR_FILES <= names or names - SUPERVISOR_FILES:
        raise Refusal("run directory is not a fresh supervisor-created directory")
    manifest = read_json(binding)
    if (manifest.get("schema") != "crypto.autoresearch.nistseed_ecpp_trial_binding.v1" or
            manifest.get("cohort_index") != index or
            Path(manifest.get("output_directory", "")).resolve() != output.resolve() or
            manifest.get("frozen_input_sha256") != digests or manifest.get("limits") != LIMITS or
            manifest.get("primary_configuration") != PRIMARY):
        raise Refusal("exact binding manifest mismatch")
    launch = read_json(output / "launch.json")
    argv = json.loads((output / "command.txt").read_text(encoding="utf-8"))
    if launch.get("argv") != argv or str(index) not in argv or str(output) not in argv:
        raise Refusal("supervisor launch/argv mismatch")
    return manifest

def safe_files(root: Path) -> dict[str, str]:
    answer = {}
    for path in root.rglob("*"):
        if not path.is_file() or path.is_symlink():
            continue
        relative = path.relative_to(root)
        if ".." in relative.parts or not path.resolve().is_relative_to(root.resolve()):
            raise Refusal("artifact path escapes trial output")
        answer[relative.as_posix()] = sha_file(path)
    return answer

def emit(output: Path, raw: dict[str, Any], observation: dict[str, Any], failure: dict[str, Any] | None) -> dict[str, Any]:
    write_json(output / "observation.json", observation)
    if failure is not None:
        write_json(output / "failure.json", failure)
    raw["driver_artifacts"] = safe_files(output / "legacy-child") if (output / "legacy-child").exists() else {}
    write_json(output / "raw-result.json", raw)
    (output / "manifest.yaml").write_text("run:\n  attack_claimed: false\n  result:\n    raw_result: raw-result.json\n", encoding="utf-8")
    return raw

def run_trial(index: int, output: Path, binding: Path,
              legacy_call: Callable[[int, Path], dict[str, Any]] | None = None) -> dict[str, Any]:
    if type(index) is not int or not 0 <= index < 21:
        raise Refusal("cohort index outside [0,20]")
    digests = verify_frozen()
    rows, runtime = load_cohort()
    verify_supervisor(output, binding, index, digests)
    mapping = prior_mapping(rows)
    row = rows[index]
    child = output / "legacy-child"
    if child.exists() or (output / "runtime-cache").exists():
        raise Refusal("duplicate trial execution refused")
    raw = {"schema": "crypto.autoresearch.nistseed_ecpp_raw_result.v3", "cohort_index": index,
           "curve": row, "binding_manifest_sha256": sha_file(binding), "frozen_input_sha256": digests,
           "runtime_payloads": runtime["artifacts"], "kernel": runtime["kernel"],
           "original_data": runtime["original_data"], "limits": LIMITS, "primary_configuration": PRIMARY,
           "supervisor_artifact_sha256": {name: sha_file(output / name) for name in SUPERVISOR_FILES},
           "named_orders_executed": 1}
    observation = {"curve_uid": row["curve_uid"], "prior_primality_evidence": mapping[row["curve_uid"]],
                   "mathematical_classification": "INDETERMINATE", "legacy_labels_observation_only": [],
                   "stage": "not_started", "unprinted_state": "UNOBSERVED"}
    try:
        if legacy_call is None:
            sys.path.insert(0, str(COMPAT))
            import cohort_case
            legacy_call = cohort_case.execute_case
        result = legacy_call(index, child)
        observation.update(result)
        serial = (child / "prover" / "serial.raw").read_bytes()
        labels = [item.decode() for item in re.findall(rb"^(?:% )?This number is (prime|composite)\b", serial, re.M)]
        observation["legacy_labels_observation_only"] = labels
        observation["trace"] = extract_trace(serial)
        observation["stage"] = "prover_returned"
        admitted = result.get("certificate_admitted") is True
        observation["mathematical_classification"] = "PRIOR_PRIMALITY_EVIDENCE_REQUIRED" if admitted else "INDETERMINATE"
        raw["classification"] = observation["mathematical_classification"]
        raw["censoring"] = not admitted
        return emit(output, raw, observation, None)
    except BaseException as error:
        raw["classification"] = "INDETERMINATE"
        raw["censoring"] = True
        observation.setdefault("censor_reason", type(error).__name__ + ": " + str(error))
        if (child / "prover" / "serial.raw").is_file():
            serial = (child / "prover" / "serial.raw").read_bytes()
            observation["legacy_labels_observation_only"] = [item.decode() for item in re.findall(rb"^(?:% )?This number is (prime|composite)\b", serial, re.M)]
            observation["trace"] = extract_trace(serial)
            observation["stage"] = "partial_prover"
        return emit(output, raw, observation, {"exception": type(error).__name__, "message": str(error), "classification": "INDETERMINATE"})

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--index", required=True, type=int)
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--input-binding-manifest", required=True, type=Path)
    args = parser.parse_args()
    print(json.dumps(run_trial(args.index, args.output, args.input_binding_manifest), sort_keys=True))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Independent fail-closed checker for the future one-index ECPP driver."""
from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
COMPAT = ROOT / "research/nist_seed_ecpp_compat_20261024"
DATA = COMPAT / ".work/build-v4/ECPP/Ecpp/Data"
sys.path.insert(0, str(COMPAT))
from certificate_admission import admit, parse
from guest_framing import valid_frame

class CheckFailure(RuntimeError):
    pass

def fail(message: str) -> None:
    raise CheckFailure(message)

def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

def load(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))

def require_artifact(raw: dict[str, Any], output: Path, name: str) -> Path:
    path = output / "legacy-child" / name
    expected = raw.get("driver_artifacts", {}).get(name)
    if not path.is_file() or path.is_symlink() or sha(path) != expected:
        fail("missing, symlinked, or mutated driver artifact: " + name)
    return path

def strict_trace(serial: bytes) -> dict[str, Any]:
    raw = (DATA / "ecpp.DfD").read_bytes()
    catalog: dict[int, list[dict[str, Any]]] = {}
    for ordinal, match in enumerate(re.finditer(rb"\(\(([^)]*)\)\s+(-?\d+)\s+(-?\d+)\)", raw)):
        value = int(match.group(2))
        catalog.setdefault(value, []).append({"file": "ecpp.DfD", "record": ordinal,
            "byte_offset": match.start(2), "line": raw.count(b"\n", 0, match.start(2)) + 1,
            "factors": match.group(1).decode("ascii").split(), "sign_code": int(match.group(3))})
    patterns = [("phase", rb"^% Starting phase [^\r\n]*$"), ("proving_job", rb"^% Starting proving job for step \d+$"),
                ("recursive_N", rb"^% N_(\d+)=(\d+)$"), ("recursive_status", rb"^% N_\d+ is (?:not )?prime$"),
                ("retry", rb"^%!% Forced to retry, snif\.\.\.$"), ("D", rb"^% (?:next D is |D\[\[\d+\]=)(-?\d+)$"),
                ("factor_route", rb"^% (?:Factorization completed using |Using complete factorization theorem).*?$"),
                ("unknown_marker", rb"^%!?%?.*$")]
    events = []
    for line in re.finditer(rb"[^\n]*(?:\n|$)", serial):
        item = line.group(0).rstrip(b"\n").rstrip(b"\r")
        for kind, expression in patterns:
            found = re.match(expression, item)
            if found:
                event = {"kind": kind, "printed": True, "source_offset": line.start(), "raw_utf8": item.decode("utf-8", "replace")}
                if kind == "D":
                    event["value"] = int(found.group(1)); event["catalog_positions"] = catalog.get(event["value"], [])
                elif found.groups():
                    event["value"] = [group.decode("ascii") for group in found.groups()]
                events.append(event); break
    return {"schema": "trace_schema.json", "raw_serial_sha256": hashlib.sha256(serial).hexdigest(), "events": events,
            "unprinted_state": "UNOBSERVED", "inference_prohibited": "unprinted branches are not reconstructed as attempted"}

def check(output: Path) -> dict[str, Any]:
    raw = load(output / "raw-result.json")
    observation = load(output / "observation.json")
    binding = output / "input-binding-manifest.json"
    if raw.get("schema") != "crypto.autoresearch.nistseed_ecpp_raw_result.v3" or not binding.is_file() or raw.get("binding_manifest_sha256") != sha(binding):
        fail("raw result or retained binding manifest mismatch")
    binding_value = load(binding)
    if binding_value.get("cohort_index") != raw.get("cohort_index") or Path(binding_value.get("output_directory", "")).resolve() != output.resolve():
        fail("binding identity mismatch")
    if raw.get("classification") not in ("INDETERMINATE", "PRIOR_PRIMALITY_EVIDENCE_REQUIRED") or raw.get("censoring") != (raw.get("classification") == "INDETERMINATE"):
        fail("classification/censoring mismatch")
    stage = observation.get("stage")
    if stage == "not_started":
        if raw["classification"] != "INDETERMINATE" or not (output / "failure.json").is_file():
            fail("early censored failure lacks envelope")
        return {"accepted": True, "classification": "INDETERMINATE", "censored_stage": "not_started"}
    serial = require_artifact(raw, output, "prover/serial.raw").read_bytes()
    prover = observation.get("prover")
    if not isinstance(prover, dict):
        fail("prover status missing")
    strict = valid_frame(prover.get("qemu_exit"), serial, prover.get("reason"))
    if observation.get("trace") != strict_trace(serial):
        fail("trace is not independently recomputed")
    labels = [value.decode() for value in re.findall(rb"^(?:% )?This number is (prime|composite)\b", serial, re.M)]
    if labels != observation.get("legacy_labels_observation_only"):
        fail("legacy labels are not raw-serial derived")
    if stage == "partial_prover":
        if raw["classification"] != "INDETERMINATE" or not (output / "failure.json").is_file():
            fail("partial censored observation mismatch")
        return {"accepted": True, "classification": "INDETERMINATE", "censored_stage": "partial_prover"}
    if not strict or prover.get("child_exit") != 0:
        if raw["classification"] != "INDETERMINATE":
            fail("invalid framing must be censored")
        return {"accepted": True, "classification": "INDETERMINATE", "censored_stage": "prover"}
    admitted = observation.get("certificate_admitted") is True
    if not admitted:
        if raw["classification"] != "INDETERMINATE":
            fail("non-admitted observation must be censored")
        return {"accepted": True, "classification": "INDETERMINATE", "censored_stage": "admission"}
    certificate = require_artifact(raw, output, "prover/certificate.cformat").read_bytes()
    checker_serial = require_artifact(raw, output, "checker/serial.raw")
    checker_stdout = require_artifact(raw, output, "checker/program.stdout").read_bytes()
    checker = observation.get("checker")
    if labels != ["prime"] or not isinstance(checker, dict) or not valid_frame(checker.get("qemu_exit"), checker_serial.read_bytes(), checker.get("reason")):
        fail("admitted record has inconsistent labels/checker framing")
    try:
        steps = parse(certificate, int(raw["curve"]["n"]))
    except (ValueError, UnicodeError) as error:
        fail("certificate root/grammar failure: " + str(error))
    if not admit(checker, checker_stdout, certificate, int(raw["curve"]["n"])):
        fail("legacy checker rejection")
    if observation.get("certificate_steps") != steps or observation.get("certificate_sha256") != hashlib.sha256(certificate).hexdigest():
        fail("certificate step count/digest mismatch")
    if raw["classification"] != "PRIOR_PRIMALITY_EVIDENCE_REQUIRED":
        fail("admitted classification mismatch")
    return {"accepted": True, "classification": raw["classification"],
            "legacy_certificate_component": "bounded legacy grammar/root/step component; not an independent general primality verifier"}

def aa_compare(left: dict[str, Any], right: dict[str, Any]) -> dict[str, Any]:
    required = {"fixture", "trace", "prover", "checker", "certificate", "classification", "labels", "runtime"}
    if not all(isinstance(value, dict) and required <= set(value) for value in (left, right)):
        fail("incomplete A/A fixture")
    for value in (left, right):
        fixture = value["fixture"]
        if not isinstance(fixture, dict) or not isinstance(fixture.get("id"), str) or "curve_uid" in fixture or "n" in fixture:
            fail("A/A fixture must be a non-cohort public fixture")
    def semantic(value: dict[str, Any]) -> dict[str, Any]:
        return {key: value[key] for key in required}
    if semantic(left) != semantic(right):
        fail("A/A semantic mismatch")
    return {"mode": "A/A", "equal": True,
            "scope": "non-cohort engineering reproducibility control only; not an independent curve or cohort order"}

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path)
    parser.add_argument("--aa-left", type=Path)
    parser.add_argument("--aa-right", type=Path)
    args = parser.parse_args()
    value = aa_compare(load(args.aa_left), load(args.aa_right)) if args.aa_left and args.aa_right else check(args.output)
    print(json.dumps(value, sort_keys=True))

if __name__ == "__main__":
    main()

